def test_scan_with_projection_expression(self, dynamodb, table): """Scan with ProjectionExpression to return only specific attributes.""" dynamodb.put_item( TableName=table, Item={"pk": {"S": "proj-1"}, "a": {"S": "x"}, "b": {"S": "y"}, "c": {"S": "z"}}, ) resp = dynamodb.scan( TableName=table, FilterExpression="pk = :pk", ExpressionAttributeValues={":pk": {"S": "proj-1"}}, ProjectionExpression="pk, a", ) assert len(resp["Items"]) >= 1 item = resp["Items"][0] assert "pk" in item assert "a" in item > assert "b" not in item E AssertionError: assert 'b' not in {'a': {'S': 'x'}, 'b': {'S': 'y'}, 'c': {'S': 'z'}, 'pk': {'S': 'proj-1'}}
